DEFAULT_SELECTIVE_DOMAIN = False
SELECTIVE_DOMAIN = "enable_selective_domain"

SSL_CLIENT_CERT_FIELD = "ssl_client_cert"
SSL_CLIENT_KEY_FIELD = "ssl_client_key"

# Special marker key used by EndpointConfig to indicate 449 status
# without raising an exception
MISSING_DOMAIN_MARKER = "missing_domain"

SESSION_START_REJECTION_MESSAGE = (
    "Session was already started for the current message. "
    "Skipping execution of action_session_start."
)

STREAMING_QUEUE_MAX_SIZE = 32

# Metadata key added to BotUttered events that were constructed from chunks
# already delivered to the output channel via streaming.  _send_bot_messages
# checks for this key and skips the send_response() call so the voice channel
# does not replay content the user has already heard.
STREAMED_CHUNK_KEY = "streamed_chunk"

# Internal key attached to each entry in an executor's ``streamed_payloads`` list
# to record which streaming response (one stream_start/stream_chunk/stream_end
# cycle, identified by the SDK's ``response_id``) the chunk belongs to. Used by
# ``aggregate_streamed_payloads`` to avoid merging text across separate streaming
# responses. Stripped before the payload becomes a BotUttered; never sent to the
# output channel. Named ``streaming_response_id`` to avoid confusion with the
# conversation session id.
STREAMING_RESPONSE_ID_KEY = "streaming_response_id"

# Field name used by the rasa-sdk gRPC ``Chunk`` and ``ChunkStart`` proto
# messages to carry the streaming-response identifier. Defined here so that
# the gRPC executor does not scatter the bare string "response_id" across
# multiple call sites.
GRPC_RESPONSE_ID_FIELD = "response_id"
